  left: 7px !important;
  top: 59px !important;
  transform: rotate(-90deg) translateY(-50%) !important;
  transform-origin: left center !important;
  font-size: 7px !important;
  color: #82454b !important; 
  letter-spacing: 1px !important;
  white-space: nowrap !important;
  z-index: 10;
}

.mesAvatarWrapper::after {
  content: "愛" !important; /* 💜 */
  position: absolute !important;
  right: 2px !important;
  bottom: 2px !important;
  width: 18px !important;
  height: 18px !important;
  color: #75020f !important; 
  font-size: 10px !important;
  line-height: 16px !important;
  text-align: center !important;
  font-weight: 900 !important;
  z-index: 10 !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><filter id="r"><feTurbulence type="fractalNoise" baseFrequency="0.15" numOctaves="3"/><feDisplacementMap in="SourceGraphic" scale="8"/></filter><rect x="5" y="5" width="90" height="90" fill="none" stroke="%2375020f" stroke-width="10" filter="url(%23r)"/></svg>') !important; 
  background-size: contain !important;
  background-repeat: no-repeat !important;
  filter: opacity(.85) !important;
}

.mes .name_text {
  position: absolute !important;
  left: 130px !important;
  top: 165px !important;
  font-size: 1.4em !important;
  font-weight: 700 !important;
  color: #ffe8eb !important; 
  letter-spacing: 2px !important;
  z-index: 10;
  background: #1a1011 !important; 
  padding: 2px 8px !important;
  border: 1px solid #75020f !important; 
  text-shadow: none !important;
}

.mes .name_text::after {
  content: "Love is a bleeding wound." !important; /* 💜 */
  display: block !important;
  position: absolute;
  left: 0;
  top: -18px;
  font-size: 8px !important;
