  color: #bd5561 !important; 
  font-size: 9px !important;
  padding: 2px 6px !important;
  border: 1px solid #75020f !important; 
  z-index: 10 !important;
  font-style: normal;
  border-top: 1px solid #75020f; 
  width: auto;
}

/* ★2. UI 全局深度重构 */
* {
  border-radius: 0 !important;
}

.text_pole,
textarea,
select,
.menu_button,
.character_select,
.group_select,
input[type="text"],
input[type="number"] {
  background-color: #241618 !important; 
  border: 1px solid #5c242c !important; 
  color: #e5d0d3 !important; 
  border-radius: 0 !important;
  box-shadow: 2px 2px 0 rgba(0, 0, 0, .2) !important;
  transition: all .2s ease;
}

.text_pole:focus,
textarea:focus,
select:focus {
  border-color: #75020f !important; 
  box-shadow: 2px 2px 0 rgba(117, 2, 15, .3) !important; 
  outline: none !important;
}

.menu_button {
  background-color: #291619 !important; 
  font-weight: 700;
}

.menu_button:hover {
  background-color: #451a20 !important; 
  color: #FFFFFF !important;
}

.inline-drawer-toggle,
.list-group-item,
.drawer-content .list-group-item,
#extensions_menu .inline-drawer-toggle {
  background: #241618 !important; 
  background-image: none !important;
  border: 1px solid #5c242c !important; 
  margin: 6px 8px !important;
  box-shadow: 2px 2px 0 rgba(0, 0, 0, .3) !important;
  color: #e5d0d3 !important; 
  font-weight: 700 !important;
  padding: 10px 15px !important;
  transition: all .2s ease !important;
}

.inline-drawer-toggle:hover,
.list-group-item:hover {
  background: #451a20 !important; 
  border-color: #75020f !important; 
  transform: translate(-1px, -1px);
  box-shadow: 3px 3px 0 rgba(117, 2, 15, .3) !important; 
  color: #FFFFFF !important;
}

.inline-drawer-toggle i,
.inline-drawer-toggle .fa-chevron-down,
.inline-drawer-toggle .fa-chevron-right,
.inline-drawer-icon {
  color: #75020f !important; 
  text-shadow: none !important;
}

#right-nav h4,
#left-nav h4,
.inline-drawer-header h4,
.standoutHeader,
.drawer-content h4 {
  background: #140e0f !important; 
  color: #bd5561 !important; 
  border: 1px solid #140e0f !important; 
  padding: 8px 12px !important;
  margin: 15px 8px 10px 8px !important;
  letter-spacing: 2px !important;
  text-transform: uppercase;
  font-size: 14px !important;
  box-shadow: 3px 3px 0 #0c0708 !important; 
  text-align: center !important;
  text-shadow: none !important;
}

.mes_text h1,
.mes_text h2,
.mes_text h3,
.mes_text h4 {
  background: transparent !important;
  color: #ffe8eb !important; 
  border: none !important;
  border-bottom: 1px solid #4d3237 !important; 
  box-shadow: none !important;
  margin: 15px 0 10px 0 !important;
  padding: 0 0 5px 0 !important;
  text-align: left !important;
}

#completion_prompt_manager_list {
  background-color: transparent !important;
  border: none !important;
}

#completion_prompt_manager_list .completion_prompt_manager_prompt_name.text_muted,
#completion_prompt_manager_list .completion_prompt_manager_prompt_name *,
#completion_prompt_manager_list .text_muted,
.completion_prompt_manager_prompt_name {
  color: #ccb6b9 !important; 
  opacity: 1 !important;
  -webkit-text-fill-color: #ccb6b9 !important; 
  text-shadow: none !important;
}

input[type="range"] {
  -webkit-appearance: none !important;
  appearance: none !important;
  background: #451a20 !important; 
  height: 3px !important;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
  filter: none !important;
  mix-blend-mode: normal !important;
  opacity: 1 !important;
  overflow: visible !important;
}

/* 保持滑块图标原色 */
input[type="range"]::-webkit-slider-thumb,
input[type="range"]::-moz-range-thumb {
  -webkit-appearance: none !important;
  width: 34px !important;
  height: 24px !important;
  background: url('https://files.catbox.moe/dtkz8w.png') center/contain no-repeat !important;
  border: 0 !important;
  border-radius: 0 !important;
  filter: drop-shadow(1px 1px 2px rgba(0, 0, 0, .6)) !important;
}

input[type="checkbox"] {
  border-radius: 0 !important;
  -webkit-appearance: none;
  appearance: none;
  background: 0 0 !important;
  border: 1px solid #5c242c !important; 
  width: 16px;
  height: 16px;
  position: relative;
  vertical-align: middle;
  cursor: pointer;
  outline: none !important;
}

input[type="checkbox"]:checked {
  border-color: #75020f !important; 
  background: 0 0 !important;
}

input[type="checkbox"]::before {
  content: none !important;
}

input[type="checkbox"]:checked::after {
  content: '' !important;
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%) !important;
  width: 14px;
  height: 14px;
  background: url('https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAETDY5p3dzrHJzABytWPPppRE9WDKO6cAAC6zEAAhLf8Fa2C-1QMNU61zsE.jpg') center/cover no-repeat !important;
  filter: contrast(1.2) invert(.8) !important;
}

::-webkit-scrollbar {
  display: none;
}

/* 顶栏常亮并增加毛玻璃背景 */
#top-bar {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  width: 100% !important;
  padding: 4px 0 !important;
  z-index: 3005 !important;
  opacity: 1 !important;
  background: rgba(20, 16, 16, 0.5) !important; 
  backdrop-filter: blur(4px) !important;
  -webkit-backdrop-filter: blur(4px) !important;
  transition: all .3s ease !important;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.2) !important;
}

.drawer-icon {
  transform: scale(.55);
  color: #ffe8eb !important; 
  filter: drop-shadow(0 0 2px rgba(0, 0, 0, 0.8)) !important;
}

#mes_stop i::before {
  font-size: 16px;
}

#send_form {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  width: 94% !important;
  max-width: 800px;
  margin: 10px auto !important;
  background: #1a1011 !important; 
  border: 1px solid #3a1519 !important; 
  border-radius: 0 !important;
  box-shadow: 4px 4px 0 rgba(0, 0, 0, .3) !important;
}

#nonQRFormItems {
  padding: 4px 12px !important;
  position: relative;
  display: flex;
  flex-direction: row;
  column-gap: 5px;
  order: 25;
  width: 100%;
  min-height: 40px !important;
  align-items: center;
  overflow: hidden;
  background-color: #1a1011 !important; 
  border: none !important;
  box-shadow: none !important;
  z-index: 50;
}

.qr--buttons {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  margin: 0 !important;
  padding: 0 !important;
