  transition: all .3s cubic-bezier(.2, 1, .3, 1);
  overflow: hidden;
}

#send_form:focus-within .qr--buttons {
  opacity: 1;
  visibility: visible;
  max-height: 300px;
  margin-bottom: 8px !important;
  transform: translateY(0);
  pointer-events: auto;
}

#rightSendForm>div:not(.mes_stop),
#leftSendForm>div {
  transform: scale(.6) !important;
  color: #75020f; 
}

#send_textarea {
  background: 0 0 !important;
  border: 0 !important;
  box-shadow: none !important;
  color: #ffe8eb !important; 
}

#send_textarea::placeholder,
#send_textarea::-webkit-input-placeholder {
  color: transparent !important;
  opacity: 0 !important;
  -webkit-text-fill-color: transparent !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: "No escape, my dear." !important; /* 💜 */
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  transform: translate(-50%, -50%) !important;
  font-style: italic !important;
  font-size: 10px !important;
  pointer-events: none !important;
  z-index: 10 !important;
  white-space: nowrap !important;
  color: #82454b !important; 
  letter-spacing: 1px;
}

#chat {
  -webkit-mask-image: linear-gradient(to bottom, transparent 0, #000 15px, #000 calc(100% - 25px), transparent 100%);
  mask-image: linear-gradient(to bottom, transparent 0, #000 15px, #000 calc(100% - 25px), transparent 100%);
}

.mes_reasoning_details {
  width: 100% !important;
  margin: 15px 0 !important;
  border: 0 !important;
  background: 0 0 !important;
  overflow: visible !important;
}

.mes_reasoning_header,
.mes_reasoning_summary,
.mes_reasoning_header_text {
  background: #291619 !important; 
  background-image: none !important;
  box-shadow: none !important;
  border-radius: 0 !important;
}

.mes_reasoning_summary {
  width: 100% !important;
  box-sizing: border-box !important;
  border: 1px solid #451a20 !important; 
  border-left: 4px solid #75020f !important; 
  padding: 0px 15px !important;
  color: #ffe8eb !important; 
  position: relative !important;
  display: flex !important;
  align-items: center !important;
  min-height: 32px !important;
